import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"正则与表情包","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/regex-stickers.md","filePath":"guide/agent/regex-stickers.md","lastUpdated":1789295632000}'),i={name:"guide/agent/regex-stickers.md"};function l(n,a,s,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="正则与表情包" tabindex="-1">正则与表情包 <a class="header-anchor" href="#正则与表情包" aria-label="Permalink to &quot;正则与表情包&quot;">​</a></h1><p>角色编辑页里两个偏「进阶」的功能：正则负责改写消息内容，表情包让角色能发贴纸。</p><h2 id="正则" tabindex="-1">正则 <a class="header-anchor" href="#正则" aria-label="Permalink to &quot;正则&quot;">​</a></h2><p>正则对匹配到的消息应用过滤规则，典型用途是屏蔽特定词、格式化输出。</p><h3 id="规则字段" tabindex="-1">规则字段 <a class="header-anchor" href="#规则字段" aria-label="Permalink to &quot;规则字段&quot;">​</a></h3><ul><li><strong>正则表达式</strong>：JavaScript 正则语法，匹配到的内容会被处理。写错语法会提示无效。</li><li><strong>作用对象</strong>（可多选）：用户消息 / AI 输出。</li><li><strong>作用效果</strong>（可多选）： <ul><li><strong>不显示</strong>：用户端看不到匹配内容。</li><li><strong>AI 看不见</strong>：匹配内容不会发给模型。</li></ul></li></ul><p>两个效果可以同时勾选（用户看不到、模型也看不到），也可以只勾一个——比如只勾「不显示」，让用户看不到某些符号但模型仍能读到完整信息。</p><p>原始消息始终保留：编辑某条消息时能看到完整内容。</p><h3 id="测试预览" tabindex="-1">测试预览 <a class="header-anchor" href="#测试预览" aria-label="Permalink to &quot;测试预览&quot;">​</a></h3><p>编辑页提供测试：输入一段测试文本，按当前<strong>未保存</strong>的规则同时预览「用户端显示」和「发送给 AI」两种结果。保存前先试，避免规则误伤正常内容。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p>屏蔽 AI 输出里的某个口癖词：作用对象选「AI 输出」，效果勾「不显示」，填入对应正则即可——用户看不到这个词，但角色自己不知道被过滤了，表现依然自然。</p><h2 id="角色表情包" tabindex="-1">角色表情包 <a class="header-anchor" href="#角色表情包" aria-label="Permalink to &quot;角色表情包&quot;">​</a></h2><p>给角色配置专属贴纸包，它会根据对话的情绪和场景自主选择发送，单独成行显示为方形贴纸（开启分段输出时独占一个气泡）。</p><h3 id="添加表情包" tabindex="-1">添加表情包 <a class="header-anchor" href="#添加表情包" aria-label="Permalink to &quot;添加表情包&quot;">​</a></h3><p>在角色编辑页的「表情包」里逐个添加：</p><ul><li><strong>标识（key）</strong>：1-32 位，仅字母、数字、下划线和短横线，角色内唯一。它会出现在语法 <code>[[agent_sticker key=标识]]</code> 中。</li><li><strong>描述（必填）</strong>：模型据此判断「什么情绪、什么场景下用这张」。写清楚触发情境，比如「得意时挑眉笑」，角色才知道什么时候掏出来。留空无法保存。</li><li><strong>图片</strong>：任意比例的图片或动图，不超过 5MiB。</li></ul><p><strong>AI 生成描述</strong>：懒得写描述可以让识图模型看图生成，费用按识图单价从你的余额扣除。</p><h3 id="会话中的表情设置" tabindex="-1">会话中的表情设置 <a class="header-anchor" href="#会话中的表情设置" aria-label="Permalink to &quot;会话中的表情设置&quot;">​</a></h3><ul><li><strong>启用智能体表情包</strong>：总开关。开启后用户与角色都可以发全站表情，角色还能按描述自主选择全站表情和专属贴纸。</li><li><strong>每轮表情包上限</strong>：单条回复中全站表情与贴纸合计的上限（0-10，0 为关闭），超出部分自动移除。怕角色刷屏就调小。</li></ul><h3 id="前提-全站表情需要描述" tabindex="-1">前提：全站表情需要描述 <a class="header-anchor" href="#前提-全站表情需要描述" aria-label="Permalink to &quot;前提：全站表情需要描述&quot;">​</a></h3><p>角色能选用哪些全站自定义表情，取决于管理员是否为该表情填写了「智能体描述」。想让自己配的表情也参与，联系管理员补描述即可。</p><h2 id="使用语法" tabindex="-1">使用语法 <a class="header-anchor" href="#使用语法" aria-label="Permalink to &quot;使用语法&quot;">​</a></h2><p>对话里表情的书写方式见<a href="/guide/agent/syntax#表情与贴纸">对话语法</a>：全站表情用 <code>:名字:</code>，角色贴纸由角色以 <code>[[agent_sticker key=标识]]</code> 语法发出。</p>',24)])])}const p=e(i,[["render",l]]);export{u as __pageData,p as default};
